const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function derive(a,m,f){
 const mcTvl=ratio(m?.market_cap,f?.tvl),fdvTvl=ratio(m?.fully_diluted_valuation,f?.tvl);
 const feeYield=ratio((f?.fees30d??null)!=null?f.fees30d*12:null,m?.fully_diluted_valuation);
 const revYield=ratio((f?.revenue30d??null)!=null?f.revenue30d*12:null,m?.fully_diluted_valuation);
 const dilution=ratio(m?.fully_diluted_valuation,m?.market_cap);
 const circulating=m?.circulating_supply??null,total=m?.total_supply??null,max=m?.max_supply??null;
 const supplyBase=max??total,unlockedPct=circulating!=null&&supplyBase>0?circulating/supplyBase*100:null;
 const remainingPct=unlockedPct==null?null:Math.max(0,100-unlockedPct);
 let dilutionRisk=null;
 if(unlockedPct!=null){dilutionRisk=Math.round(clamp(unlockedPct,0,100))}
 else if(dilution!=null){dilutionRisk=Math.round(clamp(100/dilution,0,100))}
 const fields=[m?.market_cap,m?.fully_diluted_valuation,m?.total_volume,f?.tvl,f?.tvl7d,f?.tvl1m,f?.fees30d,f?.revenue30d];
 const coverage=Math.round(fields.filter(v=>v!=null).length/fields.length*100);
 let momentum=null;
 if(f?.tvl7d!=null||f?.tvl1m!=null){momentum=50+(f?.tvl7d??0)*1.5+(f?.tvl1m??0)*.7;momentum=Math.round(clamp(momentum,0,100))}
 let valuation=null;
 if(fdvTvl!=null||feeYield!=null||revYield!=null){
   let pts=50;
   if(fdvTvl!=null)pts+=fdvTvl<1?18:fdvTvl<3?8:fdvTvl>10?-15:0;
   if(feeYield!=null)pts+=feeYield>.15?15:feeYield>.05?8:feeYield<.01?-8:0;
   if(revYield!=null)pts+=revYield>.08?15:revYield>.02?7:revYield<.005?-8:0;
   valuation=Math.round(clamp(pts,0,100));
 }
 const liveEvidence=momentum!=null&&valuation!=null?Math.round(momentum*.45+valuation*.55):null;
 return{mcTvl,fdvTvl,feeYield,revYield,dilution,circulating,total,max,unlockedPct,remainingPct,dilutionRisk,coverage,momentum,valuation,liveEvidence};
}
