function useHistoricalReplay(auth){
 const[observations,setObservations]=useState([]),[outcomes,setOutcomes]=useState([]),[status,setStatus]=useState("idle");
 async function refresh(){if(!supabase||!auth.session?.user){setObservations([]);setOutcomes([]);setStatus("idle");return}
  setStatus("loading");
  // PostgREST caps each response at 1000 rows; replay outcomes exceed that quickly, so read every page.
  const pageAll=async q=>{const rows=[];for(let f=0;;f+=1000){const{data,error}=await q().range(f,f+999);if(error)return{data:null,error};rows.push(...(data||[]));if(!data||data.length<1000)break}return{data:rows,error:null}};
  const[{data:o,error:oe},{data:x,error:xe}]=await Promise.all([
   pageAll(()=>supabase.from("historical_replay_observations").select("*").order("observed_date",{ascending:false}).order("id",{ascending:false})),
   pageAll(()=>supabase.from("historical_replay_outcomes").select("*").order("matured_at",{ascending:false}).order("id",{ascending:false}))
  ]);
  if(oe||xe){console.error(oe||xe);setStatus("error")}else{setObservations(o||[]);setOutcomes(x||[]);setStatus("live")}
 }
 useEffect(()=>{refresh()},[auth.session?.user?.id]);
 return{observations,outcomes,status,refresh}
}
function HistoricalReplayPanel({asset,replay}){
 const obs=(replay?.observations||[]).filter(x=>x.research_asset_id===asset.id);
 const outs=(replay?.outcomes||[]).filter(x=>x.research_asset_id===asset.id);
 const med=a=>{const x=a.filter(Number.isFinite).sort((a,b)=>a-b);return x.length?x[Math.floor(x.length/2)]:null};
 const cohorts=[
  ["Above 50D + 200D",x=>x.trend_state==="ABOVE_50_200"],
  ["RSI 45–65",x=>Number(x.rsi_14)>=45&&Number(x.rsi_14)<=65],
  ["BTC-relative 30D > 0",x=>Number(x.btc_relative_30d)>0],
  ["30D pullback",x=>Number(x.return_30d)<0]
 ];
 const rows=cohorts.map(([label,test])=>{
  const ids=new Set(obs.filter(test).map(x=>x.id)),o=outs.filter(x=>ids.has(x.replay_observation_id)&&x.horizon_days===30);
  return{label,n:o.length,ret:med(o.map(x=>Number(x.asset_return_pct))),rel:med(o.map(x=>Number(x.btc_relative_return_pct))),dd:med(o.map(x=>Number(x.max_drawdown_pct)))}
 });
 return <section className="panel historicalReplay"><h3><Database size={17}/> Historical Replay · v9.2</h3>
  <p className="sourceNote">Leakage-safe quantitative replay from point-in-time price and BTC history. It does not backfill historical Thesis, Setup, fundamentals, qualitative evidence, regime or AI judgments.</p>
  {replay?.status==="error"?<p className="err">Replay data unavailable.</p>:!obs.length?<p>No replay observations stored yet. Run the historical-replay worker after deploying v9.2.</p>:<>
   <div className="miniGrid"><div><small>REPLAY OBSERVATIONS</small><b>{obs.length}</b></div><div><small>FORWARD OUTCOMES</small><b>{outs.length}</b></div></div>
   <div className="historyTable"><div className="historyRow head"><span>30D cohort</span><span>Samples</span><span>Median return</span><span>vs BTC</span><span>Median max DD</span></div>
   {rows.map(r=><div className="historyRow" key={r.label}><span>{r.label}</span><span>{r.n}</span><span>{r.ret==null?"—":pct(r.ret)}</span><span>{r.rel==null?"—":pct(r.rel)}</span><span>{r.dd==null?"—":pct(r.dd)}</span></div>)}</div>
   <p className="sourceNote">Small samples are descriptive, not probabilities. v9.2 does not tune thresholds automatically.</p>
  </>}
 </section>
}
